CREATE TABLE `Pessoa` (`id` INTEGER NOT NULL AUTO_INCREMENT, `nome` VARCHAR(150) NOT NULL, `email` VARCHAR(254) NOT NULL, `tipo` ENUM('SOLICITANTE','TECNICO') NOT NULL, `ativo` BOOLEAN NOT NULL DEFAULT true, `criadoEm` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `atualizadoEm` DATETIME(3) NOT NULL, UNIQUE INDEX `Pessoa_email_key`(`email`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `TipoProblema` (`id` INTEGER NOT NULL AUTO_INCREMENT, `nome` VARCHAR(120) NOT NULL, `ativo` BOOLEAN NOT NULL DEFAULT true, `criadoEm` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `atualizadoEm` DATETIME(3) NOT NULL, UNIQUE INDEX `TipoProblema_nome_key`(`nome`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Chamado` (`id` INTEGER NOT NULL AUTO_INCREMENT, `titulo` VARCHAR(100) NOT NULL, `descricao` TEXT NOT NULL, `prioridade` ENUM('BAIXA','MEDIA','ALTA','CRITICA') NOT NULL DEFAULT 'MEDIA', `situacao` ENUM('ABERTO','EM_ATENDIMENTO','RESOLVIDO','FECHADO','CANCELADO') NOT NULL DEFAULT 'ABERTO', `solicitanteId` INTEGER NOT NULL, `tecnicoId` INTEGER NULL, `tipoProblemaId` INTEGER NOT NULL, `resolvidoEm` DATETIME(3) NULL, `criadoEm` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `atualizadoEm` DATETIME(3) NOT NULL, INDEX `Chamado_situacao_prioridade_idx`(`situacao`,`prioridade`), INDEX `Chamado_solicitanteId_idx`(`solicitanteId`), INDEX `Chamado_tecnicoId_situacao_idx`(`tecnicoId`,`situacao`), INDEX `Chamado_tipoProblemaId_idx`(`tipoProblemaId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Comentario` (`id` INTEGER NOT NULL AUTO_INCREMENT, `conteudo` TEXT NOT NULL, `chamadoId` INTEGER NOT NULL, `autorId` INTEGER NOT NULL, `criadoEm` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `Comentario_chamadoId_criadoEm_idx`(`chamadoId`,`criadoEm`), INDEX `Comentario_autorId_idx`(`autorId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Chamado` ADD CONSTRAINT `Chamado_solicitanteId_fkey` FOREIGN KEY (`solicitanteId`) REFERENCES `Pessoa`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Chamado` ADD CONSTRAINT `Chamado_tecnicoId_fkey` FOREIGN KEY (`tecnicoId`) REFERENCES `Pessoa`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Chamado` ADD CONSTRAINT `Chamado_tipoProblemaId_fkey` FOREIGN KEY (`tipoProblemaId`) REFERENCES `TipoProblema`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Comentario` ADD CONSTRAINT `Comentario_chamadoId_fkey` FOREIGN KEY (`chamadoId`) REFERENCES `Chamado`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Comentario` ADD CONSTRAINT `Comentario_autorId_fkey` FOREIGN KEY (`autorId`) REFERENCES `Pessoa`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
